pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address attacker, address recipient, uint256 amount) public {
        vm.assume(attacker != address(this));
        vm.deal(address(c), amount);
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));
        bool reverted = !success;
        assertTrue(reverted);
    }
}
